import*as Root from"../root/root.js";const registeredAppProvider=[];export function registerAppProvider(r){registeredAppProvider.push(r)}export function getRegisteredAppProviders(){return registeredAppProvider.filter((r=>Root.Runtime.Runtime.isDescriptorEnabled({experiment:void 0,condition:r.condition}))).sort(((r,e)=>(r.order||0)-(e.order||0)))}